/// PARSE MESSAGE
// Reads the Forkcast form: body.preferences (comma-separated) and body.menuUrl.
const item = $input.first().json;

const url = (item.body?.menuUrl ?? '').trim().replace(/[).,!?]+$/, '');
if (!/^https?:\/\//i.test(url)) {
  throw new Error('No menu link received. Send a restaurant or menu URL.');
}

const FORM_PREFS = {
  'gluten intolerance': 'gluten-sensitive (not coeliac)',
  'lactose intolerance': 'dairy intolerant',
  vegetarian: 'vegetarian',
  vegan: 'vegan',
};

const diets = [...new Set(
  (item.body?.preferences ?? '')
    .split(',')
    .map(p => FORM_PREFS[p.trim().toLowerCase()])
    .filter(Boolean)
)].join(', ') || FORM_PREFS['gluten intolerance'];

return [{ json: { url, diets } }];

// FORMAT REPLY
// Splits the RESTAURANT / LOCATION lines off the top of the agent's reply
// and returns them as separate fields for the Forkcast frontend.
const raw = $input.first().json.output ?? '';

const meta = {};
const message = raw
  .replace(/^[ \t*_]*(RESTAURANT|LOCATION)[ \t*_]*:(.*)$/gim, (_, key, value) => {
    meta[key.toLowerCase()] = value;
    return '';
  })
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// Treat "unknown" / "N/A" / "not listed" as no value
const clean = (value) => {
  const text = (value ?? '').replace(/[*_]+/g, '').trim();
  return text && !/^(unknown|n\/?a|none|not (found|listed|provided|available))\.?$/i.test(text) ? text : null;
};

return [{
  json: {
    message,
    restaurantName: clean(meta.restaurant),
    location: clean(meta.location),
  },
}];
